    uint32_t        iM,    // i : max hcode index
    uint64_t*       hcode)       // o : encoding table [HUF_ENCSIZE]
{
    const uint8_t* p  = *pcode;
    uint64_t       c  = 0;
    uint64_t       ni = *nLeft;
    uint64_t       nr;
    uint32_t       lc = 0;
    uint64_t       l, zerun;

    memset (hcode, 0, sizeof (uint64_t) * HUF_ENCSIZE);
    for (; im <= iM; im++)
