static inline exr_result_t
outputBits (
    int       nBits,
    uint64_t  bits,
    uint64_t* c,
    int*      lc,
    uint8_t** outptr,
    uint8_t*  outend)
{
    uint8_t* out = *outptr;
    *c <<= nBits;
    *lc += nBits;
    *c |= bits;

    while (*lc >= 8)
